def populate_notification_event_keys(apps, schema_editor):
    """
    Заполняет event_key для уведомлений, созданных до Notification Core.

    Бюджетные уведомления получают ключ, который впоследствии
    будет использовать NotificationService.

    Остальные старые записи получают индивидуальный legacy-ключ,
    чтобы сохранить уникальность и историю уведомлений.
    """

    Notification = apps.get_model("notifications", "Notification")
    database = schema_editor.connection.alias

    notifications = (
        Notification.objects.using(database)
        .filter(event_key__isnull=True)
        .only("id", "budget_id", "notification_type")
    )

    for notification in notifications.iterator():
        if notification.budget_id is not None:
            notification.event_key = (
                f"budget:{notification.budget_id}:"
                f"{notification.notification_type}"
            )
        else:
            notification.event_key = (
                f"legacy:notification:{notification.pk}"
            )

        notification.save(
            using=database,
            update_fields=["event_key"],
        )


